from dataclasses import dataclass
@dataclass(frozen=True, slots=True, repr=False)
class Some:
    _0: object
    def __repr__(self):
        return f"Some({self._0!r})"
@dataclass(frozen=True, slots=True, repr=False)
class None_:
    def __repr__(self):
        return "None_"
_None_ = None_()
def _pf_map_try_find(k, m):
    if k in m:
        return Some(m.get(k))
    return _None_
@dataclass(frozen=True, slots=True)
class P:
    x: int
    y: int
m = dict([(1, P(1, 2))])
def f(k):
    match _pf_map_try_find(k, m):
        case Some(P(x=x, y=y)):
            return x + y
        case None_():
            return 0
        case _:
            raise RuntimeError("non-exhaustive match")
